package com.personal.assistant.module.calendar.service;
import com.personal.assistant.module.calendar.dto.CalendarEventRequest;import com.personal.assistant.module.calendar.entity.CalendarCustomEvent;import com.personal.assistant.module.calendar.mapper.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.jdbc.core.JdbcTemplate;import java.time.LocalDateTime;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class CalendarServiceTest{@Mock JdbcTemplate jdbc;@Mock CalendarCustomEventMapper custom;@Mock CalendarEventOverrideMapper overrides;@InjectMocks CalendarService service;@Test void createKeepsOwnerAndRecurrence(){ArgumentCaptor<CalendarCustomEvent>captor=ArgumentCaptor.forClass(CalendarCustomEvent.class);LocalDateTime start=LocalDateTime.of(2026,7,30,9,0);service.create(7L,new CalendarEventRequest("晨间复盘",null,start,start.plusHours(1),false,"PENDING","#5275f5","WEEKLY",true));verify(custom).insert(captor.capture());assertEquals(7L,captor.getValue().getUserId());assertEquals("WEEKLY",captor.getValue().getRecurrenceRule());assertTrue(captor.getValue().getWorkdayOnly());}}
